import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Day CERN 2019: CephFS: looking for the Swiss Army knife of POSIX filesystems - Mattia Belluco","description":"","frontmatter":{"title":"Ceph Day CERN 2019: CephFS: looking for the Swiss Army knife of POSIX filesystems - Mattia Belluco","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["CephFS","POSIX 文件系统","分布式存储","Ceph","HPC 环境"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_CephFS_-_looking_for_the_Swiss_Army_knife_of_POSIX_filesystems_-_Mattia_Belluco.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_CephFS_-_looking_for_the_Swiss_Army_knife_of_POSIX_filesystems_-_Mattia_Belluco.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Day_CERN_2019_-_CephFS_-_looking_for_the_Swiss_Army_knife_of_POSIX_filesystems_-_Mattia_Belluco.md"};function _(r,l,s,h,n,p){return i(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>Ceph文件系统（CephFS）在HPC环境中的应用与挑战</p><h4 id="主讲人" tabindex="-1">主讲人 <a class="header-anchor" href="#主讲人" aria-label="Permalink to &quot;主讲人&quot;">​</a></h4><p>Matteo Bellucco</p><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><p>下午</p><h4 id="会议地点" tabindex="-1">会议地点 <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点&quot;">​</a></h4><p>苏黎世大学</p><h4 id="会议内容概述" tabindex="-1">会议内容概述 <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述&quot;">​</a></h4><p>Matteo Bellucco分享了苏黎世大学在HPC环境中使用CephFS的经验，包括需求分析、CephFS的选择原因、测试过程、生产部署以及未来规划。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>存储系统需求</strong>：</p><ul><li>POSIX兼容性</li><li>可靠性（RAID 6）</li><li>可扩展性和可伸缩性</li><li>性能</li><li>成本效益</li><li>附加需求：配额、灵活性、避免单点性能下降等</li></ul></li><li><p><strong>选择CephFS的原因</strong>：</p><ul><li>长期使用Ceph作为OpenStack部署的后端存储</li><li>Ceph的可靠性和可扩展性</li><li>Ceph Luminous版本的丰富功能，特别是覆盖复活池和纠删码策略</li></ul></li><li><p><strong>测试过程</strong>：</p><ul><li>使用小型测试床进行初步测试</li><li>遇到的问题包括ZLO元数据访问性能问题、缓存压力响应失败等</li><li>解决策略包括增加元数据池的存储空间、升级到Luminous版本等</li></ul></li><li><p><strong>生产部署</strong>：</p><ul><li>部署了新的Ceph集群，包括三个监控节点和120个SATA硬盘</li><li>使用NVMe作为RocksDB和元数据池的存储</li><li>遇到的问题包括硬件不足、配额支持的实现等</li></ul></li><li><p><strong>未来的计划</strong>：</p><ul><li>简化文件系统设置，利用CephFS的多重挂载支持</li><li>增加更激进的纠删码策略和压缩，减少成本</li><li>提供用户可访问的定期快照，以防止数据丢失或修改</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>选择CephFS作为HPC环境的存储解决方案</li><li>部署新的Ceph集群，并逐步解决遇到的问题</li><li>未来将简化文件系统设置，提高系统的容错性和成本效益</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化CephFS的配置和性能</li><li>增加更多的节点以扩展存储能力</li><li>实施定期快照功能，提高数据安全性</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语 <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语&quot;">​</a></h4><p>Matteo Bellucco总结了CephFS在HPC环境中的应用经验，并欢迎与会者提出问题。</p><p>[总结的改进之处]</p><ol><li>确保了关键细节的准确性，包括会议主题、主讲人、时间和地点。</li><li>涵盖了讨论的主要议题，包括存储需求、CephFS选择原因、测试过程、生产部署和未来规划。</li><li>确保了决定的事项和后续行动计划的完整性。</li><li>保留了计算机科学/ceph相关领域的英文原文关键词。</li></ol>',21)])])}const d=e(o,[["render",_]]);export{c as __pageData,d as default};
